# Let me create test images with different patch types in different corners
# Patch types: white square, checkerboard, random noise
# Patch sizes: 3, 4, 5 pixels
# Corners: top-left, top-right, bottom-left, bottom-right (1 pixel in from corner)

def create_patched_images(base_images, patch_size=3, patch_type='white', corner='tl'):
    """Create patched images. base_images: (N, 3, 32, 32) uint8"""
    N = base_images.shape[0]
    patched = base_images.clone()

    # Determine patch position
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, 32 - 1 - patch_size
    elif corner == 'bl':
        r, c = 32 - 1 - patch_size, 1
    elif corner == 'br':
        r, c = 32 - 1 - patch_size, 32 - 1 - patch_size

    for i in range(N):
        if patch_type == 'white':
            patch = torch.full((3, patch_size, patch_size), 255, dtype=torch.uint8)
        elif patch_type == 'checkerboard':
            patch = torch.zeros((3, patch_size, patch_size), dtype=torch.uint8)
            for ch in range(3):
                for pr in range(patch_size):
                    for pc in range(patch_size):
                        if (pr + pc) % 2 == 0:
                            patch[ch, pr, pc] = 255
        elif patch_type == 'random':
            patch = torch.randint(0, 2, (3, patch_size, patch_size), dtype=torch.uint8) * 255
        else:
            raise ValueError(f"Unknown patch_type: {patch_type}")

        patched[i, :, r:r+patch_size, c:c+patch_size] = patch

    return patched

